<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Illuminate\Support\Collection; use Pterodactyl\Models\Dezerx\StaffMessage; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Server; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Avatars; class StaffPresenter { public static function request(StaffRequest $request, User $viewer, bool $timeline = false): array { $server = $request->server; $owner = $server?->user; $isStaff = (int) $request->staff_id === $viewer->id; $isOwner = $server !== null && (int) $server->owner_id === $viewer->id; $payload = [ 'uuid' => $request->uuid, 'status' => $request->status, 'direction' => $request->direction, 'scope' => $request->scope, 'scopeLabel' => StaffPresets::LABELS[$request->scope] ?? $request->scope, 'reason' => (string) $request->reason, 'permissions' => $request->permissions ?? [], 'server' => $server === null ? null : [ 'identifier' => $server->uuidShort, 'name' => $server->name, 'egg' => $server->egg === null ? null : [ 'uuid' => (string) $server->egg->uuid, 'name' => (string) $server->egg->name, ], ], 'owner' => $owner?->username, 'ownerAvatar' => Avatars::hash($owner), 'ownerAvatarUrl' => Avatars::custom($owner), 'staff' => $request->staff?->username, 'staffAvatar' => Avatars::hash($request->staff), 'staffAvatarUrl' => Avatars::custom($request->staff), 'target' => $request->target?->username, 'openedBy' => $request->requester?->username, 'openEnded' => $request->isOpenEnded(), 'durationMinutes' => $request->duration_minutes, 'remainingMinutes' => $request->remaining_minutes, 'secondsLeft' => $request->secondsLeft(), 'requiresConfirmation' => $request->requires_confirmation === true, 'extensions' => $request->extensions, 'handoffs' => $request->handoffs, 'extensionAsk' => $request->extension_minutes === null ? null : [ 'minutes' => $request->extension_minutes, 'note' => (string) ($request->extension_note ?? ''), ], 'declineReason' => $request->decline_reason === null ? null : (string) $request->decline_reason, 'resolution' => $request->resolution === null ? null : (string) $request->resolution, 'createdAt' => $request->created_at?->toAtomString(), 'claimedAt' => $request->claimed_at?->toAtomString(), 'startedAt' => $request->started_at?->toAtomString(), 'expiresAt' => $request->expires_at?->toAtomString(), 'endedAt' => $request->ended_at?->toAtomString(), 'feedback' => StaffReviews::of($request), 'canReview' => StaffReviews::canLeave($request, $viewer), 'canChat' => StaffChat::canRead($request, $viewer), 'canPost' => StaffChat::canWrite($request, $viewer), 'unread' => $isStaff || $isOwner ? StaffChat::unreadFor($request, $viewer) : 0, 'mine' => $isStaff, ]; if ($timeline) { $payload['timeline'] = self::timeline($request); } return $payload; } public static function collection(Collection $requests, User $viewer, bool $timeline = false): array { return $requests ->map(fn (StaffRequest $request) => self::request($request, $viewer, $timeline)) ->values() ->all(); } public static function timeline(StaffRequest $request): array { return $request->events() ->with('actor:id,username') ->orderBy('id') ->limit(200) ->get() ->map(fn ($event) => [ 'action' => $event->action, 'actor' => $event->actor?->username, 'note' => $event->note === null ? null : (string) $event->note, 'at' => $event->created_at?->toAtomString(), ]) ->values() ->all(); } public static function message(StaffMessage $message, ?User $viewer = null, ?StaffRequest $request = null): array { $author = $message->author; $owner = (int) ($request?->server?->owner_id ?? 0); $seen = $owner > 0 && (int) $message->user_id === $owner ? $request?->staff_read_at : $request?->owner_read_at; return [ 'id' => $message->id, 'author' => $author?->username, 'avatar' => Avatars::hash($author), 'avatarUrl' => Avatars::custom($author), 'own' => $viewer !== null && (int) $message->user_id === $viewer->id, 'read' => $seen !== null && $message->created_at !== null && $seen->greaterThanOrEqualTo($message->created_at), 'body' => (string) $message->body, 'at' => $message->created_at?->toAtomString(), ]; } public static function messages(Collection $messages, ?User $viewer = null, ?StaffRequest $request = null): array { return $messages ->map(fn (StaffMessage $message) => self::message($message, $viewer, $request)) ->values() ->all(); } public static function serverState(Server $server, User $viewer, Collection $requests): array { return [ 'seats' => Staff::number('max_staff_per_server'), 'seatsLeft' => Staff::seatsLeft($server->id), 'autoAccept' => Staff::autoAcceptFor($viewer), 'requests' => self::collection($requests, $viewer, true), ]; } } 